pub struct Orders(Vec<Order>);                     // field private: no leak

impl Orders {
    pub fn add(&mut self, order: Order) -> Result<(), OrderError> {
        if self.0.len() >= MAX_ORDERS {
            return Err(OrderError::Full);
        }
        self.0.push(order);                        // the only write path
        Ok(())
    }
    pub fn as_slice(&self) -> &[Order] { &self.0 } // read-only view, not &Vec
}

impl AsRef<[Order]> for Orders {
    fn as_ref(&self) -> &[Order] { &self.0 }
}
